"""Knuckle_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python Knuckle_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Solid, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 30.0    # level along z

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 30.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(0.0, 0.0), P(20.0, 0.0)),
    cf.segment(P(20.0, 0.0), P(20.0, 70.0)),
    Edge.makeThreePointArc(P(20.0, 70.0), P(22.9289, 77.0711), P(30.0, 80.0)),
    cf.segment(P(30.0, 80.0), P(60.0, 80.0)),
    Edge.makeThreePointArc(P(60.0, 80.0), P(67.0711, 77.0711), P(70.0, 70.0)),
    cf.segment(P(70.0, 70.0), P(70.0, 0.0)),
    cf.segment(P(70.0, 0.0), P(90.0, 0.0)),
    cf.segment(P(90.0, 0.0), P(90.0, 90.0)),
    Edge.makeThreePointArc(P(90.0, 90.0), P(87.0711, 97.0711), P(80.0, 100.0)),
    cf.segment(P(80.0, 100.0), P(10.0, 100.0)),
    Edge.makeThreePointArc(P(10.0, 100.0), P(2.9289, 97.0711), P(0.0, 90.0)),
    cf.segment(P(0.0, 90.0), P(0.0, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- off-axis bosses and holes: (start point, axis direction, diameter, length) ----
for p, u, d, h, op in [
    ((45.0, 100.0, 15.0), (0.0, 1.0, 0.0), 25.0, 25.0, "add"),
    ((-0.375, 25.25, 15.0), (1.0, 0.0, 0.0), 15.0, 20.75, "cut"),
    ((69.625, 25.25, 15.0), (1.0, 0.0, 0.0), 15.0, 20.75, "cut"),
    ((45.0, 125.25, 15.0), (0.0, -1.0, 0.0), 10.0, 25.25, "cut"),
]:
    c = Solid.makeCylinder(d / 2, h, Vector(*p), Vector(*u))
    part = part + c if op == "add" else part - c

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "Knuckle_exact.step")
